		t.Fatalf("page 1 = %+v", page)
	}
	cur := page.NextCursor
	page.Items, page.NextCursor = nil, ""
	e.MustDo(http.StatusOK, "GET", "/v1/customers?limit=2&cursor="+url.QueryEscape(cur), e.Acme.Key, nil, &page)
