func TestRequestID(t *testing.T) {
	e := apitest.New(t)
	r := e.DoWith("GET", "/v1/org", e.Acme.Key, nil, http.Header{"X-Request-Id": {"abc-123"}})
	if got := r.Header.Get("X-Request-Id"); got != "abc-123" {
