}

// RemoveMember removes a user from an organization. Their API keys for it stop working, as they are no longer a member. It
// refuses to leave the organization without an owner (ErrLastOwner).
func (s *Store) RemoveMember(orgID, userID string) error {
	_, err := s.ChangeMember(orgID, userID, MemberChange{Remove: true}, nil)
