		delete(s.members, k)
		return Member{}, nil
	}
	cur.Role = change.Role
	s.members[k] = cur
	return cur, nil
}

// ownerCount counts an organization's owners. The caller holds the lock.
func (s *Store) ownerCount(orgID string) int {
	n := 0
	for k, m := range s.members {
		if k.org == orgID && m.Role == RoleOwner {
			n++
		}
	}
	return n
}

